import {test} from 'node:test';
import assert from 'node:assert/strict';
import * as T from '../vendor/three.module.js';
import {createState,step,interact,nearby,fire,reloadWeapon,rescue,saveState,clearLine,occupied,groundAt} from '../model.mjs';
import {AFTERLIGHT_THINGS,AFTERLIGHT_FLAGS,AFTERLIGHT_CODE,afterlightStage,afterlightGoal,cleanAfterlightFlags} from '../afterlight-world.mjs';
import {installAfterlightScene} from '../afterlight-scene.mjs';
const dt=1/120,at=id=>AFTERLIGHT_THINGS.find(t=>t.id===id);
function pose(s,id){const t=at(id);Object.assign(s.p,{x:t.x,y:t.y,z:t.z,vx:0,vy:0,vz:0,grounded:true,climb:null,rail:null});}
function use(s,id){assert.equal(nearby(s)?.id,id);assert.ok(interact(s));}
function run(s,seconds){for(let i=0;i<seconds/dt;i++){step(s,{explorer:true},dt);s.events=[];}}
function fight(s,limit=12){for(let i=0;i<limit/dt;i++){
 const eye={x:s.p.x,y:s.p.y+1.65,z:s.p.z},b=s.drones.filter(b=>b.hp>0&&b.kind!=='target'&&Math.hypot(b.x-eye.x,b.y-eye.y,b.z-eye.z)<36&&clearLine(eye,{x:b.x,y:b.y,z:b.z},s)).sort((a,b)=>Math.hypot(a.x-eye.x,a.z-eye.z)-Math.hypot(b.x-eye.x,b.z-eye.z))[0];
 if(b){const dx=b.x-eye.x,dz=b.z-eye.z;s.p.yaw=Math.atan2(dx,-dz);s.p.pitch=Math.atan2(b.y-eye.y,Math.hypot(dx,dz));if(s.p.ammo===0)reloadWeapon(s);fire(s);}step(s,{explorer:true},dt);s.events=[];
 } }
function walk(s,x,z){let i=0;for(;i<18000;i++){const dx=x-s.p.x,dz=z-s.p.z;if(Math.hypot(dx,dz)<.18)break;s.p.yaw=Math.atan2(dx,-dz);step(s,{moveZ:Math.min(1,Math.hypot(dx,dz)),explorer:true},dt);s.events=[];}assert.ok(i<18000,'Walk blocked towards '+[x,z]+' at '+JSON.stringify(s.p));run(s,.3);}
function climb(s,axis){assert.equal(nearby(s)?.type,'ladder');interact(s);assert.ok(s.p.climb);for(let i=0;i<5000&&s.p.climb;i++)step(s,{moveZ:axis,explorer:true},dt);run(s,.6);assert.ok(!s.p.climb&&s.p.grounded);}

test('Afterlight objects are on their real floors, outside walls, with distinct use locations',()=>{for(const t of AFTERLIGHT_THINGS){assert.equal(groundAt(t.x,t.z,t.y+.1).y,t.y,t.id);assert.ok(!occupied(t.x,t.y,t.z),t.id);}assert.equal(new Set(AFTERLIGHT_THINGS.map(t=>t.id)).size,8);});
test('Old expedition flags are retained; orphan episode completion and malformed dials are rejected',()=>{
 const s=createState();const raw=JSON.parse(saveState(s));raw.expedition.flags=['regulator','afterlight-complete','afterlight-circuit'];raw.expedition.afterlightDials=[null,99,-9];const restored=createState(raw);assert.ok(restored.expedition.flags.includes('regulator'));assert.equal(afterlightStage(restored),0);assert.deepEqual(restored.expedition.afterlightDials,[0,3,0]);assert.deepEqual(cleanAfterlightFlags(['afterlight-started','afterlight-circuit']),['afterlight-started']);
});
test('Remote interaction cannot accept a dispatch or turn a workshop dial',()=>{const s=createState();interact(s);assert.equal(afterlightStage(s),0);assert.deepEqual(s.expedition.afterlightDials,[0,0,0]);});
test('Switchboard and roof reject out-of-order progress and wrong relay settings persist',()=>{const s=createState();pose(s,'afterlight-test');use(s,'afterlight-test');assert.equal(afterlightStage(s),0);pose(s,'afterlight-board');use(s,'afterlight-board');pose(s,'afterlight-beacon');use(s,'afterlight-beacon');assert.equal(s.expedition.afterlight.active,false);s.expedition.flags.push('afterlight-fuse');pose(s,'afterlight-dial-0');use(s,'afterlight-dial-0');pose(s,'afterlight-test');use(s,'afterlight-test');assert.equal(afterlightStage(s),2);assert.deepEqual(createState(saveState(s)).expedition.afterlightDials,[1,0,0]);});
test('Street encounter cannot give a fuse until both real guards are defeated; retries do not create loot or actor growth',()=>{const s=createState();for(const b of s.drones)b.hp=0;pose(s,'afterlight-board');use(s,'afterlight-board');pose(s,'afterlight-fuse');use(s,'afterlight-fuse');use(s,'afterlight-fuse');assert.equal(afterlightStage(s),1);const initial=s.drones.length;for(let j=0;j<3;j++){fight(s,7);assert.ok(s.expedition.afterlight.cleared);assert.equal(s.skirmish.gunDrops.length,0);assert.equal(s.kit.credits,400);rescue(s);pose(s,'afterlight-fuse');use(s,'afterlight-fuse');assert.ok(s.drones.length<=initial);}assert.ok(!JSON.parse(saveState(s)).expedition.afterlight);});
test('Art uses fixed pools, tracks saved state and never writes progress',()=>{const scene=new T.Scene(),art=installAfterlightScene(scene),s=createState();s.expedition.tracked='afterlight';const before=saveState(s),count=()=>{let n=0;scene.traverse(()=>n++);return n;},n=count();for(let i=0;i<100;i++)art.update(s,{reduced:i%2===0});assert.equal(count(),n);assert.equal(saveState(s),before);assert.equal(art.stats().waypoints,8);art.dispose();assert.equal(scene.children.length,0);});

test('A complete carried-state district route earns exactly one reward and restores all five milestones',()=>{
 const s=createState();for(const [x,z]of[[-10,0],[-16,-6],[-70,-8],[-84,-4]])walk(s,x,z);
 use(s,'afterlight-board');assert.equal(s.checkpoint,'bellmarket');fight(s,8);
 walk(s,-75,-20);use(s,'afterlight-fuse');fight(s,10);use(s,'afterlight-fuse');assert.equal(afterlightStage(s),2);
 for(const [x,z]of[[-88,-19],[-96,-20],[-103,-21.5],[-103,-26]])walk(s,x,z);fight(s,7);
 walk(s,-107,-26);use(s,'afterlight-clue');
 for(let i=0;i<3;i++){const t=at('afterlight-dial-'+i);walk(s,t.x,t.z);for(let n=0;n<AFTERLIGHT_CODE[i];n++)use(s,t.id);}
 walk(s,-98,-26);use(s,'afterlight-test');assert.equal(afterlightStage(s),3);
 for(const [x,z]of[[-103,-26],[-103,-21],[-97,-20],[-97,0],[-107,.1]])walk(s,x,z);climb(s,1);
 walk(s,-110,-5);use(s,'afterlight-beacon');fight(s,10);assert.equal(afterlightStage(s),3,'Timer must not be skipped by early kills');run(s,11);assert.equal(afterlightStage(s),4);
 walk(s,-107,-2.1);climb(s,-1);for(const [x,z]of[[-97,0],[-84,-4]])walk(s,x,z);const credits=s.kit.credits;use(s,'afterlight-board');assert.equal(s.kit.credits,credits+240);assert.equal(afterlightStage(s),5);use(s,'afterlight-board');assert.equal(s.kit.credits,credits+240);assert.equal(s.stats.rescues,0);const restored=createState(saveState(s));assert.equal(afterlightStage(restored),5);assert.equal(restored.kit.credits,s.kit.credits);assert.equal(restored.expedition.afterlight.active,false);assert.equal(restored.drones.filter(b=>b.afterlight).length,0);
});
